import{_ as t,o as a,c as r,ae as o}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"SOTA: Rust TUI Libraries (2026)","description":"","frontmatter":{},"headers":[],"relativePath":"sota-rust-tui-2026.md","filePath":"sota-rust-tui-2026.md"}'),i={name:"sota-rust-tui-2026.md"};function s(n,e,d,c,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="sota-rust-tui-libraries-2026" tabindex="-1">SOTA: Rust TUI Libraries (2026) <a class="header-anchor" href="#sota-rust-tui-libraries-2026" aria-label="Permalink to &quot;SOTA: Rust TUI Libraries (2026)&quot;">​</a></h1><p>State-of-the-art survey of terminal UI libraries for Rust, with recommendations for the HeliosLab / Phenotype monorepo. Survey date: 2026-06-10.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>For new Rust TUI work in 2026, <strong>use <a href="https://ratatui.rs/" target="_blank" rel="noreferrer">Ratatui</a></strong> (current <code>0.30.x</code> line). It is the de-facto industry standard, powers tools at Netflix, OpenAI, Vercel, AWS, Hugging Face, GitButler, and Electronic Arts (21k+ stars, 31M+ crates.io downloads, 4,200+ dependent crates). For the HeliosLab <code>phenoctl</code> operator UI this matches what we already ship — see <code>pheno-cli/src/tui.rs</code>.</p><h2 id="ratatui-recommended" tabindex="-1">Ratatui (recommended) <a class="header-anchor" href="#ratatui-recommended" aria-label="Permalink to &quot;Ratatui (recommended)&quot;">​</a></h2><ul><li><strong>Crate:</strong> <code>ratatui</code> (<a href="https://crates.io/crates/ratatui" target="_blank" rel="noreferrer">https://crates.io/crates/ratatui</a>)</li><li><strong>Latest:</strong> <code>0.30.1</code> (June 2026 line). The <code>0.30.0</code> release reorganized the crate into a modular workspace: <code>ratatui-core</code>, <code>ratatui-widgets</code>, <code>ratatui-crossterm</code>, <code>ratatui-termion</code>, <code>ratatui-termwiz</code>, <code>ratatui-macros</code>. Application authors should keep depending on the umbrella <code>ratatui</code> crate.</li><li><strong>Backend model:</strong> pluggable. Defaults to <strong>Crossterm</strong> (Linux/macOS/Windows) with optional <strong>Termion</strong> and <strong>Termwiz</strong> backends.</li><li><strong>Rendering:</strong> <strong>immediate mode</strong> — the app re-renders a full <code>Frame</code> every tick, Ratatui diffs against a back-buffer and writes only the delta to the TTY. This gives predictable layout and works cleanly with <code>no_std</code> / embedded targets.</li><li><strong>DX:</strong> new <code>ratatui::run()</code> convenience wrapper, builder widgets (<code>Block::bordered()</code>), <code>Stylize</code> short-hand, <code>Layout::vertical([...])</code> / <code>Layout::horizontal([...])</code> arrays, 100% documented, Discord + Matrix + Discourse forum.</li><li><strong>Ecosystem:</strong> charts, sparklines, tables, gauges, calendars, scrollable lists, <code>tui-textarea</code>, <code>ratatui-image</code>, <code>color-eyre</code> integration, etc.</li></ul><h2 id="tui-rs-legacy-do-not-use" tabindex="-1">tui-rs (legacy / do not use) <a class="header-anchor" href="#tui-rs-legacy-do-not-use" aria-label="Permalink to &quot;tui-rs (legacy / do not use)&quot;">​</a></h2><p><code>tui-rs</code> was the original Rust TUI library. It was abandoned by its maintainer in early 2023 and was forked into <strong>Ratatui</strong> by <code>@fdehau</code> and the Ratatui team. New projects should depend on <code>ratatui</code> directly. The old <code>tui</code> crate is unmaintained, has known security advisories on the buffer-double-free path, and is not receiving fixes.</p><h2 id="cursive-viable-alternative" tabindex="-1">Cursive (viable alternative) <a class="header-anchor" href="#cursive-viable-alternative" aria-label="Permalink to &quot;Cursive (viable alternative)&quot;">​</a></h2><ul><li><strong>Crate:</strong> <code>cursive</code> (<a href="https://crates.io/crates/cursive" target="_blank" rel="noreferrer">https://crates.io/crates/cursive</a>)</li><li><strong>Latest:</strong> <code>0.21.1</code>. ~4.8k stars. MIT-licensed. Still maintained, but the release cadence is much slower than Ratatui&#39;s.</li><li><strong>Backend model:</strong> Crossterm by default; also supports Termion, Pancurses, BearLibTerminal, plus a <code>dummy</code> backend for tests.</li><li><strong>Rendering:</strong> <strong>retained mode, callback-driven.</strong> You build a tree of <code>View</code>s, attach callbacks on events, and Cursive dispatches input for you. This is closer to a desktop UI toolkit (think Tk / immediate-mode GUI) than to Ratatui&#39;s redraw-every-frame model.</li><li><strong>When Cursive wins:</strong> small, form-heavy apps (dialogs, menus, settings screens) where a retained tree and built-in focus management save you from re-implementing tab/enter/escape handling. Solid Linux-TTY support, including <code>cursive-flexi-logger-view</code> and <code>cursive-tabs</code> extensions.</li><li><strong>When Cursive loses:</strong> dashboards, log viewers, large scrollable tables, and any UI that needs tight control over frame timing — Ratatui&#39;s immediate-mode model composes more naturally there.</li></ul><h2 id="recommendation-for-helioslab" tabindex="-1">Recommendation for HeliosLab <a class="header-anchor" href="#recommendation-for-helioslab" aria-label="Permalink to &quot;Recommendation for HeliosLab&quot;">​</a></h2><p><code>pheno-cli/src/tui.rs</code> already uses <code>ratatui</code> <code>0.29</code> + <code>crossterm</code> <code>0.28</code> (see <code>pheno-cli/Cargo.toml:17-18</code>). That is the correct 2026 choice. The operator surface (<code>phenoctl tui</code>) is a four-tab dashboard over the <code>.phenotype/config.db</code> (Config / Flags / Secrets / Versions), which fits Ratatui&#39;s <code>Tabs</code> + <code>List</code> + <code>Paragraph</code> widget set perfectly and renders in well under one frame budget on commodity terminals.</p><p>The only migration we should consider in the near term is bumping to the <code>0.30.x</code> line so we can adopt the new <code>ratatui::run()</code> / <code>ratatui::init()</code> helpers and the modular workspace split, which trims compile time on <code>pheno-cli</code> and unblocks the <code>ratatui-widgets</code> reuse path for future shared widgets in the Phenotype monorepo.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Ratatui website: <a href="https://ratatui.rs/" target="_blank" rel="noreferrer">https://ratatui.rs/</a></li><li>Ratatui repo: <a href="https://github.com/ratatui/ratatui" target="_blank" rel="noreferrer">https://github.com/ratatui/ratatui</a></li><li>Cursive repo: <a href="https://github.com/gyscos/cursive" target="_blank" rel="noreferrer">https://github.com/gyscos/cursive</a></li><li>Cursive docs: <a href="https://docs.rs/cursive/latest/cursive/" target="_blank" rel="noreferrer">https://docs.rs/cursive/latest/cursive/</a></li><li>In-repo: <code>pheno-cli/src/tui.rs</code>, <code>pheno-cli/Cargo.toml:11-21</code></li></ul>',15)])])}const g=t(i,[["render",s]]);export{m as __pageData,g as default};
